TOPS = {
 "newcomer": {"name": "Окно для новичка", "sub": "Где новый продавец чаще всего выживает рядом с лидерами",
              "ids": ["dog_fountain", "color_foundation", "lash_serum", "tallow_balm", "shower_filter"]},
 "demand": {"name": "Волна спроса", "sub": "Где спрос и лидеры растут быстрее всего, крупные игроки включены",
            "ids": ["persimmon_soap", "color_foundation", "body_oil", "scent_diffuser", "turmeric_soap"]},
}

claims = {}
for pid, vids in VIDEO.items():
    out = []
    for v in vids:
        f = CORPUS / f"{v}.json"
        if not f.exists(): continue
        d = json.loads(f.read_text(encoding="utf-8"))
        out.append({"video": v, "product": d.get("product"), "brand": (d.get("brand_and_domain") or "").replace("([suspicious link removed])", "").strip(),
                    "revenue": d.get("revenue_claim"), "basis": d.get("revenue_basis"), "caveat": d.get("caveat")})
    claims[pid] = out
json.dump({"name": NAME, "verdict": VERDICT, "article": ARTICLE, "tops": TOPS, "claims": claims, "cred": CRED,
           "tips": [{"sec": a, "h": b, "p": c, "risk": d, "src": e} for a, b, c, d, e in TIPS]},
          open(HERE / "ru.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print("ru.json:", len(NAME), "names,", len(ARTICLE), "articles,", sum(len(v) for v in claims.values()), "video claims")
